bool VolumeTerrainEditor::Busy(const EditorPanelState& s)const{if(!s.importJobs)return false;auto active=[&](JobHandle j){auto q=s.importJobs->StateOf(j);return q==JobState::Running||q==JobState::Queued;};return (task&&active(task->job))||(navigationTask&&active(navigationTask->job));}
bool VolumeTerrainEditor::Guard(EditorPanelState& s){if(Busy(s)||draft.Active()||(loaded&&draft.Dirty())){s.showVolumeTerrain=true;error="Save or discard the separate volume source, and finish/cancel its cook before Play, export or changing project.";return false;}return true;}
void VolumeTerrainEditor::Shutdown(Renderer& r,JobSystem* jobs){draft.Cancel();for(auto j:{task?task->job:JobHandle{},navigationTask?navigationTask->job:JobHandle{},previewTask?previewTask->job:JobHandle{}})if(jobs&&j.IsValid()){jobs->Cancel(j);jobs->Wait(j);}r.DestroyMesh(mesh);mesh={};}
void VolumeTerrainEditor::Prepare(Renderer& r,const EditorPanelState& s){
 if(!loaded||!s.importJobs)return;
 if(previewTask){auto state=s.importJobs->StateOf(previewTask->job);if(state==JobState::Completed||state==JobState::Failed||state==JobState::Cancelled){
  if(previewTask->meshId==draft.source.meshId){if(state==JobState::Completed){preview=std::make_shared<MeshData>(std::move(previewTask->result));r.DestroyMesh(mesh);mesh=r.CreateMesh(*preview);}else if(previewTask->revision==draft.Revision()){error=s.importJobs->ErrorOf(previewTask->job);preview.reset();r.DestroyMesh(mesh);mesh={};}previewRevision=previewTask->revision;}
  s.importJobs->Forget(previewTask->job);previewTask.reset();}}
 if(!previewTask&&previewRevision!=draft.Revision()){auto captured=draft.source;previewTask=std::make_shared<PreviewTask>();auto work=previewTask;work->revision=draft.Revision();work->meshId=captured.meshId;work->job=s.importJobs->Submit([work,captured](JobContext& c){std::string why;if(!BuildVolumeTerrainMesh(captured,work->result,why,[&]{return c.CancelRequested();})){if(c.CancelRequested())c.ReportCancelled();else c.SetError(why);}},JobPriority::Normal,"Volume editor preview");}
}
