bool VolumeTerrainEditor::Stroke(const Scene& scene,SceneObjectId id,glm::vec3 origin,glm::vec3 direction,bool pressed,bool down,bool cancel,bool focused,std::string& status){footprint.Clear();if(cancel&&editing){draft.Cancel();editing=false;return true;}if(!focused||!down)draft.End();if(!focused||!loaded||!editing)return false;auto* o=scene.Find(id);if(!o||!o->render||o->render->meshAsset!=draft.source.meshId){if(pressed)status="Select the open volume instance";return down;}if(glm::length(o->transform.scale-glm::vec3(1))>1e-6){status="Volume brush requires unit-scale rigid placement";return down;}auto inv=glm::inverse(o->transform.rotation);auto ro=inv*(origin-o->transform.position),rd=inv*direction;glm::vec3 hit;bool picked=preview&&PickTerrain(*preview,ro,rd,hit);
 if(!picked){float near=0,far=INFINITY;auto half=draft.source.extent*.5f;for(unsigned k=0;k<3;++k){if(std::abs(rd[k])<1e-8){if(std::abs(ro[k])>half[k])return down;}else{float a=(-half[k]-ro[k])/rd[k],b=(half[k]-ro[k])/rd[k];if(a>b)std::swap(a,b);near=std::max(near,a);far=std::min(far,b);}}if(far<near)return down;hit=ro+rd*near;}
 hit+=rd*depth;footprint.Sphere(o->transform.position+o->transform.rotation*hit,brush.radius,{1,.8f,.1f},24);if(!down)return false;bool ok=pressed?draft.Begin(hit,brush,error):(draft.Active()?draft.Continue(hit,error):true);if(!ok)status=error;return true;}
void VolumeTerrainEditor::Draw(Renderer& r,Scene& scene,ResourceManager& assets){if(!loaded)return;r.SetRenderMask(scene.Settings().mainCameraRenderMask);for(auto& o:scene.Objects())if(o.render&&o.renderVisible&&o.render->visible&&o.render->meshAsset==draft.source.meshId){r.SetRenderLayer(o.renderLayer);r.SetMaterialBindings(BuildRenderMaterialBindings(&assets,*o.render));if(preview){r.DrawMesh(mesh,o.transform.position,o.transform.rotation,o.transform.scale,{},o.render->color,o.render->alpha);}if(preview||previewRevision==draft.Revision())o.render->visible=false;}}
